/* ============ email drafts, house style ============ */
function draft(kind,e,p){const sp=e.stakeholders.find(x=>x.role==='Workstream sponsor')||{name:''};const ex=e.stakeholders.find(x=>x.role==='Executive sponsor')||{name:''};const scope=e.name||e.client;const so=(w)=>'\n\n'+(w||'Kind regards')+',\n'+me().name;const sheet=(e.docs.find(d=>/sheet/i.test(d.label))||{}).url;
  if(kind==='invite')return{to:[ex.email,sp.email].filter(Boolean).join('; '),subject:e.client+' | '+scope+' | Kickoff',body:'Hello Team,\n\nThis session will kick off '+scope+'.\n\nObjectives\n• Review the approach\n• Confirm the process for analysis\n• Identify key stakeholders: Process Owner, Technical Contact, Controls Owner\n• Review data requirements and the pseudonymised extract approach\n• Align on discovery activities, walkthrough sessions and timeline\n• Confirm next steps and responsibilities\n\nExpected outcomes\n• Agreement on scope\n• Named stakeholders\n• Alignment on data requirements\n\nLooking forward to learning more on this.'+so('Best regards')};
  if(kind==='summary'){const acts=e.tasks.filter(t=>t.phase==='kickoff'&&t.status!=='Done').map(t=>'• '+t.title+' – '+member(t.assignee).name).join('\n');return{to:'',subject:'Re: '+e.client+' | '+scope+' | Kickoff – summary and next steps',body:'Hi all,\n\nThank you so much for your time at our kickoff meeting, and we really appreciate the support for this initiative. Here is a summary of what we discussed and the next steps.\n\nLeadership\n• Executive Sponsor: '+(ex.name||'[name]')+'\n• Workstream Sponsor: '+(sp.name||'[name]')+'\n\nScope\n• '+scope+'\n\nApproach\n• Discovery and data analysis first; the focus is on listening and understanding before proposing solutions.\n• Team walkthroughs to learn how the work really gets done.\n• Findings shared with the team for approval before any solution design; any AI use case goes through the AI governance forum.\n\nData handling\n• A read-only, pseudonymised extract. All data stays within Emapta\'s network in a secured folder limited to this group.\n\nTimeline (approx. 5 weeks)\n• Weeks 1–2: mobilise, gather data and process documents, meet the team\n• Week 3: discovery and data analysis\n• Weeks 4–5: analysis, then agree findings and priorities together\n\nKey actions\n'+(acts||'• [action – owner]')+'\n\nWe\'ll reach out over the coming days for data and a little of the team\'s time, and we\'ll do our best to keep it aligned with everyone\'s schedules.\n\nLooking forward to working with you all on this.'+so('Warm regards')};}
  if(kind==='sponsor'){const ps=e.stakeholders.filter(x=>!x.role.includes('sponsor'));return{to:sp.email||'',subject:'Re: '+e.client+' | '+scope+' | Stakeholders and data',body:'Hi '+first(sp.name)+',\n\nI hope you\'re having a good week.\nBefore we reach out to the team for discovery, I would really appreciate your help to check the contacts and the data we\'d ask each of them for.\n\n'+ps.map(x=>x.name+' – '+x.role+'\n'+(x.asks||'').split('\n').filter(Boolean).map(a=>'• '+a).join('\n')).join('\n\n')+'\n\nCould you confirm this works, or let us know if there\'s someone else you\'d suggest?\n\nAll data will stay within Emapta\'s network, in a secured folder limited to our group. Please let me know if anything here is sensitive or should go through you first.\n\nOnce you\'re comfortable, I\'ll share the questionnaire and request for their time.\n\nThank you so much for your support.'+so('Warm regards')};}
  if(kind==='request')return{to:p.email||'',cc:sp.email||'',subject:'Re: '+e.client+' | '+scope+' | Pre-discovery',body:'Hi '+first(p.name)+',\n\nI hope you\'re well. As discussed with '+first(sp.name||'the sponsor')+', we\'re starting '+scope+', and we would greatly value your support as '+p.role+'. The kickoff summary is in the thread below for context.\n\nAhead of our discovery session, we\'ve prepared a short pre-discovery sheet'+(sheet?' ('+sheet+')':'')+'. It will help us understand how the work runs today and establish a baseline, so we can make the best use of your time when we meet. Please save any documents or files in your upload folder'+(p.folder?' ('+p.folder+')':'')+'.\n\nWhat we\'d appreciate:\n• Your tab ("'+(p.tab||first(p.name))+'"): '+(p.asks?p.asks.split('\n').filter(Boolean).join('; ').toLowerCase():'a few documents, baseline figures and short answers')+'. This should take about '+(p.minutes||20)+' minutes, and estimates are perfectly fine.\n• KPI Snapshot tab: current figures or estimates for the rows marked with your name.\n• Contacts: if a colleague is better placed for any item, please add their name in the sheet.\n\nItems marked Essential are the priority, and Helpful items are welcome if readily available. If it suits your schedule, it would be great to have it by '+(wd(p.due)||'[day]')+', ahead of our session.\n\nWe\'d also like to hold a short discovery session with you on '+(wd(p.session)||'[day]')+(p.focus?' to walk through '+p.focus:'')+'. Could you let me know whether that works, or suggest a time that suits you better?\n\nThank you very much for your time and support, '+first(p.name)+'.'+so()};
  if(kind==='chase')return{to:p.email||'',subject:'Re: '+e.client+' | '+scope+' | Pre-discovery',body:'Hi '+first(p.name)+',\n\nI hope your week is going well. Just a gentle nudge on the pre-discovery sheet; even the Essential items and rough estimates would help a lot ahead of our session'+(p.session?' on '+wd(p.session):'')+'.\n\nIf anything is unclear or someone else is better placed, just let me know and I\'ll follow up with them directly.\n\nThank you again for your help.'+so()};
  if(kind==='session')return{to:p.email||'',subject:e.client+' | Discovery session'+(p.session?' – '+wd(p.session):''),body:'Hi '+first(p.name)+',\n\nThank you for confirming. For our session'+(p.session?' on '+wd(p.session):'')+', we\'d like to walk through '+(p.focus||'how the work runs today, from the last real case')+'.\n\nThere\'s nothing to prepare beyond the pre-discovery sheet; if it\'s easier, share your screen and show us how you do it.\n\nLooking forward to it.'+so()};
  if(kind==='report'){const dn=e.tasks.filter(t=>t.status==='Done'&&t.due&&daysTo(t.due)>=-7);const nx=e.tasks.filter(t=>t.status!=='Done').sort((a,b)=>(a.due||'9')>(b.due||'9')?1:-1).slice(0,5);return{to:[sp.email,'azee.shaikh@emapta.com'].filter(Boolean).join('; '),subject:e.client+' | '+scope+' | Weekly update – '+fmt(today()),body:'Hi all,\n\nA short update on '+scope+'.\n\nDone this week\n'+(dn.map(t=>'• '+t.title).join('\n')||'• —')+'\n\nNext\n'+(nx.map(t=>'• '+t.title+' ('+member(t.assignee).name+(t.due?', '+fmt(t.due):'')+')').join('\n')||'• —')+'\n\nWaiting on\n'+(waitingOn(e).map(w=>'• '+w).join('\n')||'• Nothing outstanding')+'\n\nThank you all for your time and support.'+so()};}
  return{to:'',subject:'',body:''};}
